/**
 * Same maths as the generator, so a place given as {lat, lng} plots exactly
 * where the coastline says it should.
 */
export function project({ lat, lng }, { lng0, lat0, lngSpan, latSpan, width, kx }) {
  const sx = width / (lngSpan * kx);
  const sy = ((width * latSpan) / (lngSpan * kx)) / latSpan;
  return { x: (lng - lng0) * kx * sx, y: (lat0 + latSpan / 2 - lat) * sy };
}
